# frozen_string_literal: true

# Rebuild the lab workbench after every LOCAL build, so it cannot go stale.
#
# The first workbench was generated by hand on 2026-09-04 and was three weeks behind the site
# when it was checked (docs/WORKBENCH-CHECK.md). The generator reads the built pages, so the only
# moment it can be right is straight after a build. This runs it then.
#
# ONLY UNDER `jekyll serve`. The deploy runs `jekyll build`, where this does nothing: the workbench
# lives in `_site/redesign-lab/`, which the deploy deletes before upload anyway
# (.github/workflows/pages-deploy.yml:68), and the deploy should not need Python.
#
# It writes into `_site/`, never the source tree. Writing into the source would make Jekyll see a
# change and build again, which would run this again.
Jekyll::Hooks.register :site, :post_write do |site|
  next unless site.config['serving']

  script = File.join(site.source, 'tools', 'build_workbench.py')
  built = system('python', script, '--quiet')
  Jekyll.logger.warn 'Workbench:', 'not rebuilt (is Python installed? try: python tools/build_workbench.py)' unless built
end
